package com.edtech.platform.booking.dto.response;
import com.edtech.platform.booking.domain.TrialRequestStatus; import java.time.Instant; import java.util.UUID;
public record TrialRequestView(UUID id,UUID teacherId,UUID studentId,UUID subjectId,Instant preferredStartTime,String note,TrialRequestStatus status,UUID bookingId,String rejectionReason,Instant respondedAt,Instant createdAt){ public static TrialRequestView from(com.edtech.platform.booking.domain.TrialRequest r){return new TrialRequestView(r.getId(),r.getTeacherId(),r.getStudentId(),r.getSubjectId(),r.getPreferredStartTime(),r.getNote(),r.getStatus(),r.getBookingId(),r.getRejectionReason(),r.getRespondedAt(),r.getCreatedAt());} }
